import {attr, controller, target} from '@github/catalyst'
import {SinglePageWizardStepContentBase} from '../../single-page-wizard/step-content-base'
import type {StepChangeResult} from '../../single-page-wizard/wizard'
import type {TwoFactorWizardState} from './wizard-state'
import {debounce} from '@github/mini-throttle/decorators'
import {getBaseFetchHeaders} from '@github-ui/fetch-headers'

type InitiateResponse = {
  formatted_recovery_codes: string[]
  mashed_secret?: string
  qr_code_img_data?: string
  dev_otp?: string
}

@controller('two-factor-setup-verification')
export class TwoFactorSetupVerificationElement extends SinglePageWizardStepContentBase {
  @target declare appForm: HTMLFormElement
  @target declare smsForm: HTMLFormElement
  @target declare smsElem: HTMLElement
  @target declare appElem: HTMLElement
  @target declare countryCodeSelect: HTMLSelectElement
  @target declare smsPhoneInput: HTMLInputElement
  @target declare appOtpInput: HTMLInputElement
  @target declare smsOtpInput: HTMLInputElement
  @target declare qrCodeImg: HTMLImageElement
  @target declare qrCodePlaceholder: HTMLElement
  @target declare mashedSecret: HTMLElement
  @target declare smsDefaultError: HTMLElement
  @target declare smsErrorContainer: HTMLElement
  @target declare buttonSendSms: HTMLButtonElement
  @target declare smsSendStatusError: HTMLElement
  @target declare smsSendStatusInProgress: HTMLElement
  @target declare smsSendStatusSuccess: HTMLElement
  @target declare smsCodeForm: HTMLElement
  @target declare switchForm: HTMLFormElement
  @target declare appScanTextA: HTMLElement
  @target declare appScanTextB: HTMLElement
  @attr declare errorMessage: string
  declare wizardState: TwoFactorWizardState
  loaded = false
  rendered = false
  showAppWarning = false

  #eventAbortController: AbortController | null = null

  override connectedCallback() {
    // can't call super() here so matching the SinglePageWizardStepContentBase behavior that we overrode
    this.setAttribute('data-target', 'single-page-wizard-step.stepContent')
    this.initiateTwoFactorSetup('app')
    // setup event listeners
    const {signal} = (this.#eventAbortController = new AbortController())
    this.addEventListener('switch-selection', this.initiateTwoFactorSwitch, {signal})
  }

  disconnectedCallback() {
    this.#eventAbortController?.abort()
  }

  override async setStepState(wizardState: TwoFactorWizardState) {
    this.wizardState = wizardState
    if (!this.loaded) {
      document
        .getElementById('two-factor-switch-selection')
        ?.dispatchEvent(new CustomEvent('init-done', {detail: 'app'}))
      // without this check, we'd end up showing the SMS form for a split second
      // before wizardState.type is set by the connectedCallback()
      return
    }
    if (this.isAppMode()) {
      this.handleAppModeWarning()
      this.renderQRCodeImg(this.wizardState.qr_code_img_data)
      this.appOtpInput.value = this.wizardState.dev_otp || ''
      this.mashedSecret.textContent = this.wizardState.mashed_secret!
      this.smsElem.hidden = true
      this.appElem.hidden = false
    } else {
      this.appElem.hidden = true
      this.smsElem.hidden = false
    }

    if (this.rendered) {
      await this.focus()
      const focusElems = document.getElementsByClassName('js-focus')
      if (focusElems && focusElems.length > 0) {
        const firstFocusElem = focusElems[0] as HTMLElement
        if (firstFocusElem) {
          firstFocusElem.focus()
        }
      }
    }

    const switchSelectionElem = document.getElementById('two-factor-switch-selection') as HTMLElement
    if (switchSelectionElem != null) {
      switchSelectionElem.dispatchEvent(new CustomEvent('init-done', {detail: this.wizardState.type}))
    }
  }

  override async onStepRendered() {
    this.rendered = true
    this.focus()
  }

  override async focus() {
    if (this.isAppMode()) {
      this.appOtpInput.focus()
    } else {
      this.smsPhoneInput.focus()
    }
  }

  renderQRCodeImg(qr_code_img_data: string) {
    this.qrCodeImg.src = qr_code_img_data
    // Set up an onload handler to switch visibility only after image has loaded
    this.qrCodeImg.onload = () => {
      this.qrCodePlaceholder.hidden = true
      this.qrCodeImg.hidden = false
    }
  }

  isAppMode(): boolean {
    return this.wizardState.type === 'app'
  }

  handleAppModeWarning() {
    if (this.rendered && this.showAppWarning) {
      this.appScanTextA.hidden = true
      this.appScanTextB.hidden = false
    } else {
      // shows app scan warning on *next* app render
      this.showAppWarning = true
    }
  }

  override async onNextClick(): Promise<StepChangeResult<TwoFactorWizardState>> {
    this.clearError()
    const form = this.isAppMode() ? this.appForm : this.smsForm
    const csrfInput = form.querySelector('.js-data-url-csrf') as HTMLInputElement
    const formData = new FormData()
    const otp = this.isAppMode() ? this.appOtpInput.value : this.smsOtpInput.value
    formData.append('type', this.wizardState.type!)
    formData.append('otp', otp.trim())

    try {
      const response = await fetch(form.action, {
        mode: 'same-origin',
        method: 'POST',
        body: formData,
        headers: {
          Accept: 'application/json',
          'Scoped-CSRF-Token': csrfInput.value,
          ...getBaseFetchHeaders(),
        },
      })
      if (!response.ok) {
        // if it's a 429, we can use a hardcoded message here
        // the response _might_ not be JSON (e.g. secondary rate limits) so it's best to short circuit here rather then attempting to parse
        if (response.status === 429) {
          // eslint-disable-next-line i18n-text/no-en
          this.setError('Too many incorrect OTP attempts. Please try again later.')
          return {proceed: false}
        }

        // try to parse out a json error message otherwise fallback to a generic failure message
        // if the response isn't JSON, this will throw but be caught below with a generic failure message as well
        const jsonResponse = await response.json()
        if (jsonResponse['error']) {
          this.setError(jsonResponse['error'])
        } else {
          this.setError('Two-factor code verification failed. Please try again.')
        }
        return {proceed: false}
      }
    } catch {
      this.setError('Two-factor code verification failed. Please try again.')
      return {proceed: false}
    }

    const switchSelectionElem = document.getElementById('two-factor-switch-selection') as HTMLElement
    if (switchSelectionElem != null) {
      switchSelectionElem.dispatchEvent(new CustomEvent('verify-done'))
    }

    return {wizardState: this.wizardState, proceed: true}
  }

  @debounce(50)
  otpChange() {
    this.validateStep(this.isStepValid(), true)
  }

  formSubmit(e: Event) {
    e.preventDefault()
    this.otpChange()
  }

  smsPhoneInputChange() {
    this.buttonSendSms.disabled = this.smsPhoneInput.value.trim().length === 0
  }

  setSmsControlState(inProgress: boolean, isSuccess: boolean, message?: string) {
    this.buttonSendSms.disabled = inProgress || isSuccess
    const isError = !inProgress && !isSuccess
    const showDefaultError = isError && !message
    const showServerError = isError && !!message

    if (showServerError) {
      this.smsErrorContainer.querySelector('.Banner-title')!.innerHTML = message!
      setTimeout(() => this.smsErrorContainer.focus(), 0)
    }
    if (showDefaultError) {
      setTimeout(() => this.smsDefaultError.focus(), 0)
    }

    this.smsSendStatusError.hidden = !isError
    this.smsSendStatusSuccess.hidden = inProgress || !isSuccess
    this.smsSendStatusInProgress.hidden = !inProgress
    this.smsDefaultError.hidden = !showDefaultError
    this.smsErrorContainer.hidden = !showServerError
    this.smsOtpInput.disabled = inProgress || isError

    if (isSuccess) {
      this.smsCodeForm.hidden = false
      this.smsOtpInput.focus()
    }
  }

  async buttonSendSmsClick() {
    this.setSmsControlState(true, false)
    this.smsOtpInput.value = ''
    this.smsOtpInput.disabled = true
    this.validateStep(false)

    const sendSmsUrl = this.buttonSendSms.getAttribute('data-url')!
    const csrfInput = this.smsForm.querySelector('.js-data-url-csrf-send') as HTMLInputElement
    const number = `${this.countryCodeSelect.value} ${this.smsPhoneInput.value}`
    const formData = new FormData()
    formData.append('number', number)

    const octocaptchaToken = this.smsForm.querySelector('.js-octocaptcha-token') as HTMLInputElement
    if (octocaptchaToken && octocaptchaToken.value) {
      formData.append('octocaptcha-token', octocaptchaToken.value)
    }

    const response = await fetch(sendSmsUrl, {
      mode: 'same-origin',
      method: 'POST',
      body: formData,
      headers: {
        Accept: 'application/json',
        'Scoped-CSRF-Token': csrfInput.value,
        ...getBaseFetchHeaders(),
      },
    })

    if (!response.ok) {
      const jsonResponse = await response.json()
      this.setSmsControlState(false, false, jsonResponse['error'])
      return
    }
    this.smsPhoneInput.disabled = true

    this.setSmsControlState(false, true)
    if (this.wizardState.dev_otp) {
      this.smsOtpInput.value = this.wizardState.dev_otp
      this.smsOtpInput.disabled = false
      this.validateStep(this.isStepValid(), false)
      return
    }
  }

  override isStepValid(): boolean {
    const elem = this.isAppMode() ? this.appOtpInput : this.smsOtpInput
    return new RegExp(`^([0-9]{6})$`).test(elem.value)
  }

  updateHeaders(type: 'app' | 'sms') {
    const authVerificationStepElem = document.getElementById('wizard-step-factor') as HTMLElement
    const titles = authVerificationStepElem.getElementsByClassName('wizard-step-title')
    const header = titles[0] as HTMLHeadingElement
    const content = titles[1] as HTMLHeadingElement

    switch (type) {
      case 'sms':
        // eslint-disable-next-line i18n-text/no-en
        header.textContent = content.textContent = 'Setup SMS authentication'
        break
      case 'app':
        // eslint-disable-next-line i18n-text/no-en
        header.textContent = content.textContent = 'Setup authenticator app'
        break
    }
  }

  // logic for switching the current factor for verification
  // see two-factor-setup/switch-selection.ts for related code
  async initiateTwoFactorSwitch(event: Event) {
    const type = (event as CustomEvent).detail
    await this.initiateTwoFactorSetup(type)
  }

  async initiateTwoFactorSetup(type: 'app' | 'sms') {
    const csrfInput = this.switchForm.querySelector('.js-data-url-csrf') as HTMLInputElement

    const formData = new FormData()
    formData.append('type', type)

    const response = await fetch(this.switchForm.action, {
      mode: 'same-origin',
      method: 'POST',
      body: formData,
      headers: {
        Accept: 'application/json',
        'Scoped-CSRF-Token': csrfInput.value,
        ...getBaseFetchHeaders(),
      },
    })

    if (!response.ok) {
      this.setError(this.errorMessage)
      return {proceed: false}
    }

    if (this.rendered) {
      this.updateHeaders(type)
    }

    const jsonResponse = (await response.json()) as InitiateResponse
    const newWizardState: TwoFactorWizardState = {
      ...this.wizardState,
      type,
      formatted_recovery_codes: jsonResponse.formatted_recovery_codes,
      mashed_secret: jsonResponse.mashed_secret,
      qr_code_img_data: jsonResponse.qr_code_img_data || '',
      dev_otp: jsonResponse.dev_otp,
    }
    this.loaded = true
    this.setStepState(newWizardState)
  }
}
